package local.ondemand;
import android.content.*;import android.os.*;import org.json.*;import org.videolan.libvlc.interfaces.IMedia;import java.util.*;
/** Per-file observations, never a claim that an entire format is unsupported. */
final class SourceExperience {
 static String key(SourcePolicy.Source s){JSONObject h=s.raw.optJSONObject("behaviorHints");String filename=h==null?"":h.optString("filename");return filename.isEmpty()?s.fingerprint:SourcePolicy.digest("file:"+filename+":"+h.optLong("videoSize",0));}
 static void read(Context c,List<SourcePolicy.Source> sources){android.content.SharedPreferences p=c.getSharedPreferences("source-experience",0);long now=System.currentTimeMillis();for(SourcePolicy.Source s:sources){s.experienceKey=key(s);s.avoidUntil=p.getLong("avoid."+s.experienceKey,0);s.experienceNote=p.getString("reason."+s.experienceKey,"");s.verified=p.getLong("good."+s.experienceKey,0)>now-7*86400000L;if(s.verified){s.verifiedEnglish=p.getBoolean("english."+s.experienceKey,false);s.quality=p.getInt("quality."+s.experienceKey,s.quality);s.codec=p.getString("codec."+s.experienceKey,s.codec);}}}
 static void bad(Context c,String key,String reason,boolean inputWait){if(key.isEmpty())return;c.getSharedPreferences("source-experience",0).edit().putLong("avoid."+key,System.currentTimeMillis()+(inputWait?15*60*1000L:24*60*60*1000L)).putString("reason."+key,reason).remove("good."+key).apply();}
 static void good(VodPlayer p){if(p.assetKey.isEmpty())return;String codec=p.codec.toLowerCase(Locale.ROOT).contains("h264")?"H.264":p.codec.toLowerCase(Locale.ROOT).contains("hevc")?"HEVC":"";android.content.SharedPreferences.Editor e=p.context.getSharedPreferences("source-experience",0).edit().putLong("good."+p.assetKey,System.currentTimeMillis()).remove("avoid."+p.assetKey).remove("reason."+p.assetKey).putInt("quality."+p.assetKey,p.width>1920||p.height>1088?2160:p.width>1280||p.height>720?1080:720).putBoolean("english."+p.assetKey,p.selectedEnglishAudio>=0);if(!codec.isEmpty())e.putString("codec."+p.assetKey,codec);e.apply();}
 static class Tracker {
  IMedia.Stats previous;long at;int badWindows,healthyWindows;boolean recordedBad,recordedGood;
  void sample(VodPlayer p){long now=SystemClock.elapsedRealtime();if(p.engine==null||p.media==null||p.paused||p.ended||now-p.openedAt<20000||now-p.lastSeek<20000){previous=null;badWindows=healthyWindows=0;return;}IMedia.Stats s=p.media.getStats();if(s==null)return;if(previous==null){previous=s;at=now;return;}double seconds=(now-at)/1000d;int shown=Math.max(0,s.displayedPictures-previous.displayedPictures),lost=Math.max(0,s.lostPictures-previous.lostPictures),decoded=Math.max(0,s.decodedVideo-previous.decodedVideo);long input=Integer.toUnsignedLong(s.readBytes-previous.readBytes);double expected=24;try{IMedia.VideoTrack t=p.engine.getCurrentVideoTrack();if(t!=null&&t.frameRateNum>0&&t.frameRateDen>0)expected=t.frameRateNum/(double)t.frameRateDen;}catch(Exception ignored){}boolean severe=seconds>=3&&(shown/seconds<expected*.60||lost/(double)Math.max(1,shown+lost)>.20);boolean healthy=seconds>=3&&shown/seconds>=expected*.85&&lost/(double)Math.max(1,shown+lost)<.05;badWindows=severe?badWindows+1:0;healthyWindows=healthy?healthyWindows+1:0;if(badWindows>=3&&!recordedBad){boolean inputWait=input==0&&decoded==0;String reason=inputWait?"Input stopped arriving during playback":lost>0&&decoded>0?"Decoded video could not be displayed reliably":"Video output repeatedly stalled";bad(p.context,p.assetKey,reason,inputWait);recordedBad=true;recordedGood=false;}if(healthyWindows>=6&&!recordedGood){good(p);recordedGood=true;recordedBad=false;}previous=s;at=now;}
 }
}
